#pragma once
#include "graph_local_transform.h"
#include "model_skinning_geometry.h"
#include <set>
#include "session_bone_name_mapping_candidate.h"
#include "recovered_local_matrix_scale_candidate.h"
inline std::vector<GeometryMatrixCandidate> readSessionBonePoseCandidate(const Graph&graph,uint32_t model,const std::vector<GeometryBoneCandidate>&bones,bool allowScaleCandidate=false,bool allowNameMappingCandidate=false){const auto&element=graph.elements.at(model);if(graph.strings.at(element.type)!="DmeGameModel")throw std::runtime_error("pose game model required");auto attribute=namedAttribute(graph,element,"bones");if(!attribute||attribute->type!=15||attribute->values.size()!=bones.size())throw std::runtime_error("session bone array count");std::vector<uint32_t>mapped;if(allowNameMappingCandidate)mapped=sessionBoneNameMappingCandidate(graph,*attribute,bones);std::set<uint32_t>seen;std::vector<GeometryMatrixCandidate>locals;for(size_t n=0;n<bones.size();++n){auto id=allowNameMappingCandidate?mapped[n]:attribute->values[n].reference;if(id>=graph.elements.size()||!seen.insert(id).second)throw std::runtime_error("session bone reference");const auto&transform=graph.elements[id];auto label="bone "+std::to_string(n)+" ("+bones[n].name+")";if(!allowNameMappingCandidate&&graph.strings.at(transform.name)!=label)throw std::runtime_error("session/MDL bone identity: expected="+label+" actual="+graph.strings.at(transform.name));auto scaleAttribute=namedAttribute(graph,transform,"scale");float scale=1;if(scaleAttribute){if(!allowScaleCandidate)throw std::runtime_error("session bone scale pending: "+label);if(scaleAttribute->type!=3||scaleAttribute->values.size()!=1||scaleAttribute->values[0].wire.size()!=4)throw std::runtime_error("session bone scale schema: "+label);std::memcpy(&scale,scaleAttribute->values[0].wire.data(),4);if(!std::isfinite(scale)||scale<=0)throw std::runtime_error("session bone scale range: "+label);}auto matrix=graphLocalTransformMatrix(graph,id);GeometryMatrixCandidate local;for(size_t r=0;r<3;++r)for(size_t c=0;c<4;++c)local[r*4+c]=matrix[r][c];if(scaleAttribute)local=recoveredLocalMatrixScaleCandidate(local,scale);locals.push_back(local);}return locals;}
